def rank_contributors(contributors):
    """按分数降序排列贡献者。"""
    return sorted(contributors, key=lambda item: item["points"])

verification_tests:
from target import rank_contributors


def test_higher_points_comes_first():
    items = [{"name": "a", "points": 1}, {"name": "b", "points": 9}]
    assert [item["name"] for item in rank_contributors(items)] == ["b", "a"]


def test_equal_points_keep_input_order():
    items = [{"name": "a", "points": 5}, {"name": "b", "points": 5}]
    assert [item["name"] for item in rank_contributors(items)] == ["a", "b"]


def test_empty_input_returns_empty_list():
    assert rank_contributors([]) == []
